for _ in range(60):s.step(rcb_dtb.INIT_Q)
Rwo=d.xmat[obj].reshape(3,3);pwo=d.xpos[obj];Rg=Rot.from_quat([s.goals[0][3],s.goals[0][4],s.goals[0][5],s.goals[0][6]]).as_matrix();pg=np.array(s.goals[0][:3])
Rs_list=[np.column_stack([[0,1,0],[0,0,1],[1,0,0]]),np.column_stack([[0,-1,0],[0,0,1],[-1,0,0]])]
def err(p,R):
 ik.qpos[jq]=rcb_dtb.INIT_Q[:7]
 for it in range(300):
  mujoco.mj_forward(m,ik);ep=p-ik.xpos[bid];er=Rot.from_matrix(R@ik.xmat[bid].reshape(3,3).T).as_rotvec()
  if np.linalg.norm(ep)<1e-4 and np.linalg.norm(er)<1e-3:break
