 return np.linalg.norm(ep),np.linalg.norm(er),ik.xpos[bid].copy(),ik.qpos[jq].copy()
for ri,Rs in enumerate(Rs_list):
 for p0 in [[.28,.02,.50],[.30,.02,.52],[.31,.04,.50],[.30,.05,.54],[.28,.05,.53]]:
  p0=np.array(p0);rel=Rs.T@(pwo-p0);Rf=Rg@Rwo.T@Rs;pf=pg-Rf@rel;e0=err(p0,Rs);e1=err(pf,Rf)
  print('R',ri,'p0',p0,'rel',rel.round(2),'pf',pf.round(2),'err',np.round(e0[:2],2),np.round(e1[:2],2),'actual',e1[2].round(2))
